const zipContent = await browserjs(tabId, async () => {
  const res = await fetch('https://www.nyse.com/publicdocs/nyse/markets/nyse/N_MC202407.zip');
  const buf = await res.arrayBuffer();
  // Simple zip reader to find file names
  const bytes = new Uint8Array(buf);
  // Scan for local file headers PK\x03\x04
  const files = [];
  for (let i = 0; i < bytes.length - 4; i++) {
    if (bytes[i] === 0x50 && bytes[i+1] === 0x4b && bytes[i+2] === 0x03 && bytes[i+3] === 0x04) {
      const nameLen = bytes[i+26] | (bytes[i+27] << 8);
      const extraLen = bytes[i+28] | (bytes[i+29] << 8);
      const nameBytes = bytes.slice(i+30, i+30+nameLen);
      const name = new TextDecoder().decode(nameBytes);
      files.push({ name, headerOffset: i });
    }
  }
  return {
    byteLength: bytes.length,
    files
  };
});

