  ];

  async function parseZip(url) {
    const res = await fetch(url);
    const buf = await res.arrayBuffer();
    const bytes = new Uint8Array(buf);

    // Parse first local file header
    const method = bytes[8] | (bytes[9] << 8);
    const compressedSize = bytes[18] | (bytes[19] << 8) | (bytes[20] << 16) | (bytes[21] << 24);
    const uncompressedSize = bytes[22] | (bytes[23] << 8) | (bytes[24] << 16) | (bytes[25] << 24);
    const nameLen = bytes[26] | (bytes[27] << 8);
    const extraLen = bytes[28] | (bytes[29] << 8);
    const filename = new TextDecoder().decode(bytes.slice(30, 30 + nameLen));
    const dataStart = 30 + nameLen + extraLen;
    const compressedData = bytes.slice(dataStart, dataStart + compressedSize);

    let content = "";
    if (method === 0) {
      content = new TextDecoder().decode(compressedData);
    } else if (method === 8) {
      const ds = new DecompressionStream('deflate-raw');
      const writer = ds.writable.getWriter();
      writer.write(compressedData);
      writer.close();
      const reader = ds.readable.getReader();
      const chunks = [];
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
      }
      const full = new Uint8Array(chunks.reduce((acc, c) => acc + c.length, 0));
      let offset = 0;
      for (const c of chunks) {
        full.set(c, offset);
        offset += c.length;
      }
      content = new TextDecoder().decode(full);
    }
    return { filename, content, method, uncompressedSize };
  }

  const out = {};
  for (const item of urls) {
    try {
      out[item.exchange] = {
        url: item.url,
        data: await parseZip(item.url)
      };
    } catch (e) {
      out[item.exchange] = { url: item.url, error: e.message };
